import xmltodict

order = {
    "order": {
        "@id": "1001",
        "customer": "Alice",
        "items": {
            "item": [
                {"@sku": "WM-001", "name": "Wireless Mouse", "qty": "1"},
                {"@sku": "KB-002", "name": "Keyboard", "qty": "2"}
            ]
        },
        "total": "109.97"
    }
}

xml_output = xmltodict.unparse(order, pretty=True)
print(xml_output)

import xml.etree.ElementTree as ET

def validate_order(xml_string):
    try:
        root = ET.fromstring(xml_string)
    except ET.ParseError:
        return ("Invalid XML", False)

    if root.tag != "order":
        return ("Root must be 'order'", False)

    if root.get("id") is None:
        return ("Missing 'id' attribute", False)

    if root.find("customer") is None:
        return ("Missing 'customer'", False)

    return ("Valid", True)

xml_string = """<?xml version="1.0"?>
<order id="1001">
  <customer>Alice</customer>
  <items>
    <item>Mouse</item>
  </items>
</order>"""

result = validate_order(xml_string)
print(result)
